enum WebPanel {
    static let index = #"""
    <!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lustre Agent</title><style>body{margin:0;background:#101114;color:#f7f7f8;font:15px -apple-system,BlinkMacSystemFont,sans-serif}main{max-width:800px;margin:48px auto;padding:0 24px}h1{font-size:32px;margin-bottom:4px}p{color:#a9abb5}section{background:#191a1f;border:1px solid #2d2f38;border-radius:12px;padding:18px;margin-top:18px}input,button{font:inherit;border-radius:8px;padding:10px 12px}input{background:#101114;border:1px solid #393b45;color:#fff;width:calc(100% - 26px);margin:6px 0}button{background:#d64444;border:0;color:#fff;cursor:pointer;margin-top:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;color:#c7cad6}.hint{font-size:13px}</style></head><body><main><h1>Lustre Agent</h1><p>Local queue control. The provider resolver and worker are the next integration step.</p><section><label>Local API token</label><input id="token" type="password" placeholder="Run: lustre token"><button onclick="loadJobs()">Connect</button><p class="hint">Token stays only in this browser tab.</p></section><section><label>Source page URL</label><input id="url" type="url" placeholder="https://example.com/watch"><input id="quality" placeholder="Preferred quality (optional)"><button onclick="queue()">Add to queue</button><pre id="result">Not connected.</pre></section><section><h2>Jobs</h2><pre id="jobs">—</pre></section></main><script>const out=id=>document.getElementById(id);async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+out('token').value,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const x=await r.json();if(!r.ok)throw Error(x.error);return x}async function loadJobs(){try{out('jobs').textContent=JSON.stringify(await api('/v1/jobs'),null,2)}catch(e){out('jobs').textContent=e.message}}async function queue(){try{const job=await api('/v1/jobs',{sourcePageURL:out('url').value,preferredQualityLabel:out('quality').value||null,destination:'local'});out('result').textContent='Queued '+job.id;loadJobs()}catch(e){out('result').textContent=e.message}}</script></body></html>
    """#
}
